BEGIN;
CREATE SCHEMA registration_test;
CREATE FUNCTION registration_test.assert(ok boolean,msg text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF ok IS DISTINCT FROM true THEN RAISE EXCEPTION 'ASSERT: %',msg;END IF;END $$;
CREATE FUNCTION registration_test.denied(statement text) RETURNS void LANGUAGE plpgsql SECURITY INVOKER AS $$ BEGIN BEGIN EXECUTE statement;EXCEPTION WHEN OTHERS THEN RETURN;END;RAISE EXCEPTION 'Expected rejection: %',statement;END $$;
GRANT USAGE ON SCHEMA registration_test TO anon,authenticated;GRANT EXECUTE ON ALL FUNCTIONS IN SCHEMA registration_test TO anon,authenticated;
INSERT INTO auth.users(id,email) SELECT ('28000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'registration-'||n||'@example.invalid' FROM generate_series(1,6)n;
INSERT INTO public.companies(id,nome,created_by) VALUES('18000000-0000-4000-8000-000000000001','Registration fixture','28000000-0000-4000-8000-000000000001'),('18000000-0000-4000-8000-000000000002','Other fixture','28000000-0000-4000-8000-000000000001');
INSERT INTO public.company_members(company_id,user_id,role,maintenance_role,created_by) SELECT '18000000-0000-4000-8000-000000000001',('28000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'auditor',(ARRAY['admin_empresa','analista_transporte','supervisor','operador_logistico','motorista','cliente'])[n],'28000000-0000-4000-8000-000000000001' FROM generate_series(1,6)n;
SELECT set_config('request.jwt.claim.sub','28000000-0000-4000-8000-000000000001',true);
SET LOCAL ROLE authenticated;
SELECT set_config('registration_test.token',public.maintenance_partner_requests_command('18000000-0000-4000-8000-000000000001','rotate')->>'token',true);
SELECT registration_test.denied($q$SELECT public.maintenance_partner_requests_command('18000000-0000-4000-8000-000000000002','list')$q$);
RESET ROLE;
SELECT set_config('registration_test.payload','{"request_id":"68000000-0000-4000-8000-000000000001","consent":true,"declaration":true,"base":{"razao_social":"External Workshop Ltda","nome_fantasia":"External Workshop","cnpj_cpf":"11222333000181","tipo":"oficina_mecanica","especialidades":["Freios"],"tipos_veiculo_atendidos":["Caminhão"],"contato_nome":"João","telefone":"11987654321","email":"oficina@example.invalid","cep":"01001000","logradouro":"Praça da Sé","numero":"1","bairro":"Sé","cidade":"São Paulo","estado":"SP","latitude":-23.55,"longitude":-46.63,"horario_funcionamento":{},"atende_24h":true,"possui_guincho":false,"valor_hora_mao_obra":120,"prazo_pagamento_dias":30,"desconto_percentual":5},"profile":{"responsavel_legal":"João","marcas":["Volvo","Scania"],"servicos":["Freios"],"modalidades":["Corretiva"],"formas_pagamento":["Boleto faturado"],"aceita_faturado":"Sim","emite_nf":"Sim","financeiro_email":"financeiro@example.invalid"}}',true);
SET LOCAL ROLE anon;
SELECT registration_test.assert(public.maintenance_partner_registration(current_setting('registration_test.token'),'info')->>'company'='Registration fixture','public info only company');
SELECT registration_test.denied($q$SELECT * FROM public.maintenance_partner_requests$q$);
SELECT registration_test.denied($q$SELECT * FROM maintenance_private.partner_invites$q$);
SELECT registration_test.denied($q$SELECT public.maintenance_partner_requests_command('18000000-0000-4000-8000-000000000001','list')$q$);
SELECT registration_test.denied($q$SELECT public.maintenance_partner_registration(repeat('a',64),'info')$q$);
SELECT registration_test.denied($q$SELECT public.maintenance_partner_registration(current_setting('registration_test.token'),'submit',current_setting('registration_test.payload')::jsonb||'{"consent":false}')$q$);
SELECT registration_test.denied($q$SELECT public.maintenance_partner_registration(current_setting('registration_test.token'),'submit',current_setting('registration_test.payload')::jsonb||'{"website_check":"spam"}')$q$);
SELECT registration_test.denied($q$SELECT public.maintenance_partner_registration(current_setting('registration_test.token'),'submit',jsonb_set(current_setting('registration_test.payload')::jsonb,'{base,status}','"ativo"'))$q$);
SELECT registration_test.denied($q$SELECT public.maintenance_partner_registration(current_setting('registration_test.token'),'submit',jsonb_set(current_setting('registration_test.payload')::jsonb,'{base,cnpj_cpf}','"11222333000180"'))$q$);
SELECT registration_test.denied($q$SELECT public.maintenance_partner_registration(current_setting('registration_test.token'),'submit',jsonb_set(current_setting('registration_test.payload')::jsonb,'{profile,marcas}','[]'))$q$);
SELECT registration_test.assert(public.maintenance_partner_registration(current_setting('registration_test.token'),'submit',current_setting('registration_test.payload')::jsonb)->>'status'='recebida','anonymous submit');
SELECT registration_test.assert(public.maintenance_partner_registration(current_setting('registration_test.token'),'submit',current_setting('registration_test.payload')::jsonb)->>'status'='recebida','idempotent retry');
SELECT registration_test.denied($q$SELECT public.maintenance_partner_registration(current_setting('registration_test.token'),'submit',jsonb_set(current_setting('registration_test.payload')::jsonb,'{base,razao_social}','"Changed"'))$q$);
SELECT registration_test.denied($q$SELECT public.maintenance_partner_registration(current_setting('registration_test.token'),'submit',jsonb_set(current_setting('registration_test.payload')::jsonb,'{request_id}','"68000000-0000-4000-8000-000000000002"'))$q$);
RESET ROLE;
SELECT registration_test.assert((SELECT count(*)=1 FROM public.maintenance_partner_requests WHERE company_id='18000000-0000-4000-8000-000000000001'),'single pending request');
SELECT registration_test.assert(NOT EXISTS(SELECT 1 FROM public.maintenance_partners WHERE company_id='18000000-0000-4000-8000-000000000001'),'no partner before approval');
SELECT set_config('registration_test.id',(SELECT id::text FROM public.maintenance_partner_requests WHERE company_id='18000000-0000-4000-8000-000000000001'),true);
SELECT set_config('request.jwt.claim.sub','28000000-0000-4000-8000-000000000003',true);
SET LOCAL ROLE authenticated;
SELECT registration_test.assert(public.maintenance_partner_requests_command('18000000-0000-4000-8000-000000000001','list')->>'pending'='1','supervisor reads');
SELECT registration_test.denied($q$SELECT public.maintenance_partner_requests_command('18000000-0000-4000-8000-000000000001',NULL,jsonb_build_object('id',current_setting('registration_test.id')))$q$);
SELECT registration_test.denied($q$SELECT public.maintenance_partner_requests_command('18000000-0000-4000-8000-000000000001','approve',jsonb_build_object('id',current_setting('registration_test.id')))$q$);
SELECT registration_test.denied($q$SELECT public.maintenance_partner_requests_command('18000000-0000-4000-8000-000000000001','link')$q$);
SELECT set_config('request.jwt.claim.sub','28000000-0000-4000-8000-000000000005',true);
SELECT registration_test.denied($q$SELECT public.maintenance_partner_requests_command('18000000-0000-4000-8000-000000000001','list')$q$);
SELECT registration_test.assert((SELECT count(*)=0 FROM public.maintenance_partner_requests),'driver cannot read table');
SELECT set_config('request.jwt.claim.sub','28000000-0000-4000-8000-000000000002',true);
SELECT registration_test.denied($q$SELECT public.maintenance_partner_requests_command('18000000-0000-4000-8000-000000000001','reject',jsonb_build_object('id',current_setting('registration_test.id'),'note',''))$q$);
SELECT set_config('registration_test.partner',public.maintenance_partner_requests_command('18000000-0000-4000-8000-000000000001','approve',jsonb_build_object('id',current_setting('registration_test.id'),'note','Cadastro conferido'))->>'partner_id',true);
SELECT registration_test.assert((SELECT onboarding_profile->>'financeiro_email'='financeiro@example.invalid' AND prazo_pagamento_dias=30 AND status='ativo' FROM public.maintenance_partners WHERE id=current_setting('registration_test.partner')::uuid),'approval preserves full profile');
SELECT registration_test.assert((public.maintenance_partner_requests_command('18000000-0000-4000-8000-000000000001','detail',jsonb_build_object('id',current_setting('registration_test.id')))->'audit'->1->>'actor_id')=auth.uid()::text,'review audit actor');
SELECT registration_test.denied($q$SELECT public.maintenance_partner_requests_command('18000000-0000-4000-8000-000000000001','approve',jsonb_build_object('id',current_setting('registration_test.id')))$q$);
SELECT registration_test.denied($q$UPDATE public.maintenance_partner_requests SET status='pendente'$q$);
SELECT public.maintenance_partner_requests_command('18000000-0000-4000-8000-000000000001','revoke');
RESET ROLE;SET LOCAL ROLE anon;
SELECT registration_test.denied($q$SELECT public.maintenance_partner_registration(current_setting('registration_test.token'),'info')$q$);
RESET ROLE;
ROLLBACK;
